-- CI fixture ONLY. Historical dedicated-role baseline already applied to Supabase PROD.
-- Do not apply this fixture to live databases. Source: mirror migration 20261111164718.
-- Dormant, least-privilege Payroll PROD database access.
-- This migration creates NOLOGIN roles only. It does not configure a password,
-- Hostinger secret, connection URL, payment worker, journal writer or payout.
-- Application login is enabled later by an operator after DEV verification.
-- All company access is transaction-scoped through app.payroll_company_id.

DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='bizportal_payroll_prod') THEN
    EXECUTE 'CREATE ROLE bizportal_payroll_prod NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 0';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='bizportal_payroll_prod_login') THEN
    EXECUTE 'CREATE ROLE bizportal_payroll_prod_login NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 5';
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_roles
    WHERE rolname IN ('bizportal_payroll_prod','bizportal_payroll_prod_login')
      AND (rolsuper OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls)
  ) THEN
    RAISE EXCEPTION 'PAYROLL_PROD_ROLE_PRIVILEGE_DRIFT';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='bizportal_payroll_prod' AND rolcanlogin) THEN
    RAISE EXCEPTION 'PAYROLL_PROD_CAPABILITY_ROLE_MUST_NOT_LOGIN';
  END IF;
END
$roles$;

GRANT bizportal_payroll_prod TO bizportal_payroll_prod_login;
GRANT USAGE ON SCHEMA public TO bizportal_payroll_prod;

-- The existing standalone compensation tables are already installed in PROD.
-- Their broad PUBLIC policies are narrowed to the dedicated Payroll role.
DROP POLICY IF EXISTS payroll_salary_profiles_company_scoped ON public.payroll_salary_profiles;
DROP POLICY IF EXISTS payroll_deduction_settings_company_scoped ON public.payroll_deduction_settings;

-- Kasbon plans and reservations mirror the already-tested DEV schema.
-- Reservations are preparation records only; this role cannot confirm or settle them.
CREATE TABLE IF NOT EXISTS public.payroll_kasbon_auto_plans (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id INTEGER NOT NULL,
  employee_id INTEGER NOT NULL REFERENCES public.employees(id),
  advance_id INTEGER NOT NULL REFERENCES public.cash_advances(id),
  choice TEXT NOT NULL CHECK (choice IN ('FULL','INSTALLMENT')),
  installment_amount NUMERIC(18,2),
  first_period DATE NOT NULL,
  notes TEXT NOT NULL DEFAULT '' CHECK (length(notes)<=500),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT payroll_kasbon_auto_plans_unique UNIQUE(company_id,advance_id),
  CONSTRAINT payroll_kasbon_auto_plans_first_day
    CHECK (first_period=date_trunc('month',first_period::timestamp with time zone)::date),
  CONSTRAINT payroll_kasbon_auto_plans_installment_valid
    CHECK ((choice='FULL' AND installment_amount IS NULL)
       OR (choice='INSTALLMENT' AND installment_amount>0))
);

CREATE TABLE IF NOT EXISTS public.payroll_kasbon_auto_reservations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  company_id INTEGER NOT NULL,
  run_id INTEGER NOT NULL REFERENCES public.payroll_runs(id) ON DELETE RESTRICT,
  employee_id INTEGER NOT NULL REFERENCES public.employees(id) ON DELETE RESTRICT,
  payroll_item_id INTEGER NOT NULL REFERENCES public.payroll_items(id) ON DELETE RESTRICT,
  advance_id INTEGER NOT NULL REFERENCES public.cash_advances(id) ON DELETE RESTRICT,
  period DATE NOT NULL,
  amount NUMERIC(18,2) NOT NULL CHECK (amount>0),
  balance_at_preparation NUMERIC(18,2) NOT NULL CHECK (balance_at_preparation>=amount),
  state TEXT NOT NULL DEFAULT 'prepared'
    CHECK (state IN ('prepared','confirmed','cancelled')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  confirmed_at TIMESTAMPTZ,
  cancelled_at TIMESTAMPTZ,
  CONSTRAINT payroll_kasbon_auto_reservation_month_first
    CHECK (period=date_trunc('month',period::timestamp with time zone)::date),
  CONSTRAINT payroll_kasbon_auto_reservation_run_advance
    UNIQUE(company_id,run_id,advance_id)
);

CREATE INDEX IF NOT EXISTS payroll_kasbon_auto_plans_scope_idx
  ON public.payroll_kasbon_auto_plans(company_id,employee_id,advance_id);
CREATE INDEX IF NOT EXISTS payroll_kasbon_auto_reservation_employee_idx
  ON public.payroll_kasbon_auto_reservations(company_id,employee_id,period,run_id);
CREATE UNIQUE INDEX IF NOT EXISTS payroll_kasbon_auto_reservation_once_per_month
  ON public.payroll_kasbon_auto_reservations(company_id,period,advance_id)
  WHERE state IN ('prepared','confirmed');
CREATE UNIQUE INDEX IF NOT EXISTS payroll_kasbon_auto_reservation_unconfirmed_once
  ON public.payroll_kasbon_auto_reservations(company_id,advance_id)
  WHERE state='prepared';

ALTER TABLE public.payroll_kasbon_auto_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_kasbon_auto_plans FORCE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_kasbon_auto_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_kasbon_auto_reservations FORCE ROW LEVEL SECURITY;

-- Keep existing RLS enabled. The new role is neither owner nor BYPASSRLS.
ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cash_advances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.salary_payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_salary_profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.payroll_deduction_settings ENABLE ROW LEVEL SECURITY;

-- Direct browser roles previously had table grants on payroll ledgers, but their
-- deny-all RLS policies already blocked access. Remove those unused grants too.
REVOKE ALL ON TABLE public.payroll_runs,public.payroll_items,public.salary_payments
  FROM PUBLIC,anon,authenticated;
REVOKE ALL ON TABLE public.payroll_salary_profiles,public.payroll_deduction_settings,
  public.payroll_kasbon_auto_plans,public.payroll_kasbon_auto_reservations
  FROM PUBLIC,anon,authenticated;
REVOKE ALL ON TABLE public.payroll_kasbon_auto_plans,public.payroll_kasbon_auto_reservations
  FROM bizportal_payroll_prod;

-- Read-only employee and cash-advance source access. No PII beyond name/status
-- and no UPDATE/INSERT/DELETE on cash advances.
REVOKE ALL ON TABLE public.employees,public.cash_advances FROM bizportal_payroll_prod;
GRANT SELECT(id,company_id,first_name,last_name,status,deleted_at)
  ON public.employees TO bizportal_payroll_prod;
GRANT SELECT(id,company_id,employee_id,type,status,lifecycle_status,currency,amount,
  paid_amount,settled_amount,remaining_amount,approved_at,approved_by,
  disbursed_at,disbursed_by,accounting_entry_id,posting_status,voided_at)
  ON public.cash_advances TO bizportal_payroll_prod;

-- Payroll run: read/create Draft and exactly one Draft -> reviewed approval.
REVOKE ALL ON TABLE public.payroll_runs FROM bizportal_payroll_prod;
GRANT SELECT ON TABLE public.payroll_runs TO bizportal_payroll_prod;
GRANT INSERT(company_id,month,year,notes,status)
  ON public.payroll_runs TO bizportal_payroll_prod;
GRANT UPDATE(status,approved_at,notes)
  ON public.payroll_runs TO bizportal_payroll_prod;

-- Payroll items: read and insert only into a company-owned Draft.
REVOKE ALL ON TABLE public.payroll_items FROM bizportal_payroll_prod;
GRANT SELECT ON TABLE public.payroll_items TO bizportal_payroll_prod;
GRANT INSERT(run_id,employee_id,base_salary,allowance,gross_salary,
  bpjs_jht_employee,bpjs_kes_employee,pph21,other_deductions,
  kasbon_deduction,total_deductions,net_salary)
  ON public.payroll_items TO bizportal_payroll_prod;

-- Historical salary payment evidence is read-only. No salary payment writes.
REVOKE ALL ON TABLE public.salary_payments FROM bizportal_payroll_prod;
GRANT SELECT ON TABLE public.salary_payments TO bizportal_payroll_prod;

-- Effective-dated salary and deduction setup can be created/corrected, never deleted.
REVOKE ALL ON TABLE public.payroll_salary_profiles,public.payroll_deduction_settings
  FROM bizportal_payroll_prod;
GRANT SELECT,INSERT,UPDATE ON TABLE public.payroll_salary_profiles,
  public.payroll_deduction_settings TO bizportal_payroll_prod;

-- Automatic kasbon plan can be set/adjusted; prepared reservation is insert/read only.
GRANT SELECT,INSERT,UPDATE ON TABLE public.payroll_kasbon_auto_plans TO bizportal_payroll_prod;
GRANT SELECT,INSERT ON TABLE public.payroll_kasbon_auto_reservations TO bizportal_payroll_prod;

-- Identity sequences are explicitly scoped to the dedicated role.
DO $sequences$
DECLARE
  sequence_name TEXT;
BEGIN
  FOREACH sequence_name IN ARRAY ARRAY[
    pg_get_serial_sequence('public.payroll_runs','id'),
    pg_get_serial_sequence('public.payroll_items','id'),
    pg_get_serial_sequence('public.payroll_salary_profiles','id'),
    pg_get_serial_sequence('public.payroll_deduction_settings','id'),
    pg_get_serial_sequence('public.payroll_kasbon_auto_plans','id'),
    pg_get_serial_sequence('public.payroll_kasbon_auto_reservations','id')
  ] LOOP
    IF sequence_name IS NOT NULL THEN
      EXECUTE format('REVOKE ALL ON SEQUENCE %s FROM PUBLIC,anon,authenticated',sequence_name);
      EXECUTE format('GRANT USAGE,SELECT ON SEQUENCE %s TO bizportal_payroll_prod',sequence_name);
    END IF;
  END LOOP;
END
$sequences$;

-- Employee and source tables are always scoped to the authenticated company.
DROP POLICY IF EXISTS payroll_prod_employee_read ON public.employees;
CREATE POLICY payroll_prod_employee_read ON public.employees
  FOR SELECT TO bizportal_payroll_prod
  USING (company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer);

DROP POLICY IF EXISTS payroll_prod_cash_advance_read ON public.cash_advances;
CREATE POLICY payroll_prod_cash_advance_read ON public.cash_advances
  FOR SELECT TO bizportal_payroll_prod
  USING (company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer
    AND type='kasbon');

DROP POLICY IF EXISTS payroll_prod_run_read ON public.payroll_runs;
CREATE POLICY payroll_prod_run_read ON public.payroll_runs
  FOR SELECT TO bizportal_payroll_prod
  USING (company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer);
DROP POLICY IF EXISTS payroll_prod_run_insert_draft ON public.payroll_runs;
CREATE POLICY payroll_prod_run_insert_draft ON public.payroll_runs
  FOR INSERT TO bizportal_payroll_prod
  WITH CHECK (company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer
    AND status='draft' AND posting_status='pending'
    AND accounting_entry_id IS NULL AND payment_entry_id IS NULL);
DROP POLICY IF EXISTS payroll_prod_run_single_approval ON public.payroll_runs;
CREATE POLICY payroll_prod_run_single_approval ON public.payroll_runs
  FOR UPDATE TO bizportal_payroll_prod
  USING (company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer
    AND status='draft' AND posting_status='pending'
    AND approved_at IS NULL AND accounting_entry_id IS NULL AND payment_entry_id IS NULL)
  WITH CHECK (company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer
    AND status='reviewed' AND approved_at IS NOT NULL
    AND notes LIKE '%[PAYROLL_SUPER_ADMIN_APPROVAL_V1]%'
    AND posting_status='pending' AND accounting_entry_id IS NULL AND payment_entry_id IS NULL);

DROP POLICY IF EXISTS payroll_prod_item_read ON public.payroll_items;
CREATE POLICY payroll_prod_item_read ON public.payroll_items
  FOR SELECT TO bizportal_payroll_prod
  USING (EXISTS(SELECT 1 FROM public.payroll_runs r
    WHERE r.id=payroll_items.run_id
      AND r.company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer));
DROP POLICY IF EXISTS payroll_prod_item_insert_draft ON public.payroll_items;
CREATE POLICY payroll_prod_item_insert_draft ON public.payroll_items
  FOR INSERT TO bizportal_payroll_prod
  WITH CHECK (EXISTS(SELECT 1 FROM public.payroll_runs r
      JOIN public.employees e ON e.id=payroll_items.employee_id
       AND e.company_id=r.company_id AND e.status='active' AND e.deleted_at IS NULL
      WHERE r.id=payroll_items.run_id
        AND r.company_id=NULLIF(current_setting('app.payroll_company_id',true),'')::integer
        AND r.status='draft' AND r.posting_status='pending'
        AND r.accounting_entry_id IS NULL AND r.payment_entry_id IS NULL));

DROP POLICY IF EXISTS payroll_prod_salary_payment_read ON public.salary_payments;
